editorial:
For a path, either skip the newest position and keep the previous optimum, or take it and extend the optimum from two positions back. A cycle cannot use both endpoints. Solve the two paths obtained by excluding the first or last position and keep the better answer. A singleton can be taken in either version. Time O(n), auxiliary space O(1) beyond input.
~~~
#include <bits/stdc++.h>
using namespace std;

long long best(const vector<int>& a,int l,int r) {
    long long two=0,one=0;
    for (int i=l;i<r;++i) {
        long long next=max(one,two+a[i]);
        two=one;
        one=next;
    }
    return one;
}
int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int n; cin>>n;
    vector<int>a(n);
    for (int& x:a) cin>>x;
    long long line=best(a,0,n);
    cout<<line<<' '<<(n==1?line:max(best(a,1,n),best(a,0,n-1)))<<'\n';
}
